'use strict';

/*
 * The pack.toml reference page (docs/reference/pack-toml.md) matches the pack parser. Its tables are
 * generated by scripts/docs-reference.js from the parser's own constants; this file holds the
 * literal expectations on the warnings the parser gives, and on the facts the generator reads.
 *
 * The unknown-key warning tests were written before the four inline key lists in src/build/ became
 * constants, and stayed green across that refactor: they pin the warning text byte for byte.
 */

const test = require('node:test');
const assert = require('node:assert/strict');

const { parsePackToml } = require('../src/build/packtoml');

const T = '/x/pack.toml';
const parse = (text) => parsePackToml(text, { tomlPath: T, campaign: 'lease' });

// ---- characterisation: the unknown-key warnings, as literals ----

test('an unknown top-level key warns, with the literal text', () => {
  assert.deepEqual(parse('foo = 1\n').warnings, ['/x/pack.toml: unrecognised key "foo" (ignored)']);
});

test('an unknown [gm_link] key warns, with the literal text', () => {
  const r = parse('[gm_link]\nurl = "https://scriptorium.home.arpa"\nfoo = 1\n');
  assert.deepEqual(r.warnings, ['/x/pack.toml: [gm_link] unrecognised key "foo" (ignored)']);
});

test('an unknown [recaps] key warns, with the literal text', () => {
  assert.deepEqual(parse('[recaps]\nfoo = "x"\n').warnings, ['/x/pack.toml: [recaps] unrecognised key "foo" (ignored)']);
});

test('an unknown key in a [[timeline.kinds]] entry warns, with the literal text', () => {
  const r = parse('[[timeline.kinds]]\nkey = "heist"\nfoo = 1\n');
  assert.deepEqual(r.warnings, ['/x/pack.toml: [[timeline.kinds]] #1 unrecognised key "foo" (ignored)']);
});

test('an unknown [timeline] key warns, with the literal text', () => {
  assert.deepEqual(parse('[timeline]\nfoo = 1\n').warnings, ['/x/pack.toml: [timeline] unrecognised key "foo" (ignored)']);
});

test('every known key gives no warning', () => {
  const text = [
    'theme = "gloam"',
    '[images]',
    'hero = "images/example.webp"',
    '[labels]',
    'chapter = "Act"',
    '[timeline]',
    'weights = ["aside", "scene", "turning point"]',
    'session_token = "\\\\bS(\\\\d+)\\\\b"',
    'segment_units = "\\\\b(week|day)\\\\s+(\\\\d+)\\\\b"',
    '[timeline.columns]',
    'title = ["Title"]',
    '[[timeline.kinds]]',
    'key = "heist"',
    'label = "Heist"',
    'glyph = "fight"',
    'aliases = ["job"]',
    'before = true',
    '[recaps]',
    'learned_heading = "what we learned"',
    '[gm_link]',
    'url = "https://scriptorium.home.arpa"',
    '',
  ].join('\n');
  assert.deepEqual(parse(text).warnings, []);
});

// ---- literal code facts the generator reads ----

const fs = require('fs');
const path = require('path');

const gen = require('../scripts/docs-reference');
const textFile = require('../scripts/docs-reference-text');
const { INIT_DEFAULT_THEME } = require('../src/build/themes');

const ROOT = path.join(__dirname, '..');
const read = (rel) => fs.readFileSync(path.join(ROOT, rel), 'utf8');
const PACK_BLOCKS = ['pack-top', 'pack-images', 'pack-labels', 'pack-timeline', 'pack-timeline-kinds', 'pack-timeline-columns', 'pack-recaps', 'pack-gm-link'];
const keysOf = (rows) => rows.map((r) => r.key);
const byKey = (rows) => Object.fromEntries(rows.map((r) => [r.key, r]));

test('pack-top: the six top-level keys in order; theme defaults to plain and allows gloam, haze, plain', () => {
  const rows = gen.codeFacts()['pack-top'];
  assert.deepEqual(keysOf(rows), ['theme', 'images', 'labels', 'timeline', 'recaps', 'gm_link']);
  assert.equal(byKey(rows).theme.default, 'plain');
  assert.equal(byKey(rows).theme.allowed, 'gloam, haze, plain');
  assert.equal(byKey(rows).images.default, undefined);
});

test('pack-images: the six slots in order', () => {
  assert.deepEqual(keysOf(gen.codeFacts()['pack-images']), ['hero', 'ground', 'paper', 'crest-frame', 'portrait', '404']);
});

test('pack-labels: the seventeen labels in order, with their defaults', () => {
  const rows = gen.codeFacts()['pack-labels'];
  assert.deepEqual(keysOf(rows), [
    'learned_lens', 'learned_legend', 'story_lens', 'chapter', 'recap', 'recap_learned_link', 'same_recap', 'connections_heading',
    'group_tie', 'group_named', 'group_pc', 'group_npc', 'group_faction', 'group_location', 'group_thing', 'group_event', 'group_other',
  ]);
  assert.equal(byKey(rows).learned_lens.default, 'What the party learned');
  assert.equal(byKey(rows).recap_learned_link.default, 'What the Party Learned');
  assert.equal(byKey(rows).chapter.default, 'Chapter');
});

test('pack-timeline: the five keys, with the defaults the code holds', () => {
  const rows = gen.codeFacts()['pack-timeline'];
  assert.deepEqual(keysOf(rows), ['kinds', 'weights', 'session_token', 'segment_units', 'columns']);
  const d = byKey(rows);
  assert.equal(d.kinds.default, 'fight, meeting, discovery, journey, backstory');
  assert.equal(d.weights.default, 'aside, scene, turning point');
  assert.equal(d.session_token.default, '`\\bS(\\d+)\\b`');
  assert.equal(d.segment_units.default, '`\\b(week|day)\\s+(\\d+)\\b`');
  assert.equal(d.columns.default, undefined);
});

test('pack-timeline-kinds: the five entry keys; glyph allows the six built-in names', () => {
  const rows = gen.codeFacts()['pack-timeline-kinds'];
  assert.deepEqual(keysOf(rows), ['key', 'label', 'glyph', 'aliases', 'before']);
  assert.equal(byKey(rows).glyph.allowed, 'backstory, discovery, fight, journey, learned, meeting');
});

test('pack-timeline-columns: the eleven columns in order, with their default names', () => {
  const rows = gen.codeFacts()['pack-timeline-columns'];
  assert.deepEqual(keysOf(rows), ['title', 'kind', 'weight', 'place', 'in_game', 'when', 'real_world', 'what', 'session', 'learned', 'after']);
  assert.equal(byKey(rows).in_game.default, 'in-game');
  assert.equal(byKey(rows).real_world.default, 'real-world');
  assert.equal(byKey(rows).title.default, 'title');
});

test('pack-recaps and pack-gm-link: their keys, and the learned heading default', () => {
  const facts = gen.codeFacts();
  assert.deepEqual(keysOf(facts['pack-recaps']), ['learned_heading']);
  assert.equal(facts['pack-recaps'][0].default, 'what the party learned');
  assert.deepEqual(keysOf(facts['pack-gm-link']), ['url']);
});

// ---- packFacts on scratch literals ----

const SCRATCH = {
  PACK_TOP_LEVEL_KEYS: ['theme', 'other'],
  DEFAULT_THEME: 'b',
  THEMES: { b: {}, a: {} },
  SLOT_NAMES: ['s1'],
  DEFAULT_LABELS: { one: 'First' },
  DEFAULT_VOCAB: {
    kinds: [{ key: 'k1' }, { key: 'k2' }],
    weights: ['w1', 'w2', 'w3'],
    sessionToken: /x|y/,
    segmentUnits: /(u)(n)/i,
    columns: { c1: ['n1', 'n2'] },
    learnedHeading: 'heading',
  },
  TIMELINE_KEYS: ['kinds', 'weights', 'session_token', 'segment_units', 'columns'],
  KIND_ENTRY_KEYS: ['key', 'glyph'],
  GLYPH_NAMES: ['g1', 'g2'],
  RECAPS_KEYS: ['learned_heading', 'extra'],
  GM_LINK_KEYS: ['url', 'more'],
};

test('packFacts: theme allowed values come from the registry, sorted', () => {
  const f = gen.packFacts(SCRATCH);
  assert.deepEqual(f['pack-top'], [{ key: 'theme', default: 'b', allowed: 'a, b' }, { key: 'other' }]);
});

test('packFacts: every block follows its input list, with the scratch defaults', () => {
  const f = gen.packFacts(SCRATCH);
  assert.deepEqual(f['pack-images'], [{ key: 's1' }]);
  assert.deepEqual(f['pack-labels'], [{ key: 'one', default: 'First' }]);
  assert.deepEqual(f['pack-timeline'], [
    { key: 'kinds', default: 'k1, k2' },
    { key: 'weights', default: 'w1, w2, w3' },
    { key: 'session_token', default: '`x|y`' },
    { key: 'segment_units', default: '`(u)(n)`' },
    { key: 'columns' },
  ]);
  assert.deepEqual(f['pack-timeline-kinds'], [{ key: 'key' }, { key: 'glyph', allowed: 'g1, g2' }]);
  assert.deepEqual(f['pack-timeline-columns'], [{ key: 'c1', default: 'n1, n2' }]);
  assert.deepEqual(f['pack-recaps'], [{ key: 'learned_heading', default: 'heading' }, { key: 'extra' }]);
  assert.deepEqual(f['pack-gm-link'], [{ key: 'url' }, { key: 'more' }]);
});

test('renderBlock escapes the pipe in a regular expression default, once, in the code span', () => {
  const facts = gen.packFacts({ ...SCRATCH, TIMELINE_KEYS: ['session_token'] });
  const text = { 'pack-timeline': { session_token: { type: 'text', what: 'w', changedBy: 'c' } } };
  assert.equal(
    gen.renderBlock('pack-timeline', { facts, text }).split('\n')[2],
    '| `session_token` | text | `x\\|y` | - | w | c |',
  );
});

// ---- text rules ----

test('every pack block is on the pack page, in order, and nowhere else', () => {
  assert.deepEqual(gen.blockNamesIn(read('docs/reference/pack-toml.md')), PACK_BLOCKS);
  assert.deepEqual([...gen.BLOCKS_BY_TARGET['docs/reference/pack-toml.md']], PACK_BLOCKS);
});

test('the text never gives the theme default or allowed values (the code holds them)', () => {
  assert.equal(textFile['pack-top'].theme.default, undefined);
  assert.equal(textFile['pack-top'].theme.allowed, undefined);
});

test('parity: the theme text names the theme that init offers a new campaign', () => {
  assert.ok(textFile['pack-top'].theme.what.includes(`\`${INIT_DEFAULT_THEME}\``), 'the theme text must name the init default in backticks');
});

// ---- the page example ----

test('the first toml example on the page parses with no warnings', () => {
  const blocks = [...read('docs/reference/pack-toml.md').matchAll(/```toml\n([\s\S]*?)```/g)].map((m) => m[1]);
  assert.ok(blocks.length >= 1, 'the page has no toml example');
  const r = parsePackToml(blocks[0], { tomlPath: '/x/pack.toml', campaign: 'lease' });
  assert.deepEqual(r.warnings, []);
  assert.equal(r.theme, 'gloam');
  assert.equal(r.gmLink.url, 'https://scriptorium.home.arpa');
  assert.deepEqual(r.images.map((i) => i.slot), ['hero', 'ground', 'paper']);
});

test('control: a misspelt key in an example gives the literal warning', () => {
  assert.deepEqual(parse('theem = "gloam"\n').warnings, ['/x/pack.toml: unrecognised key "theem" (ignored)']);
});

// ---- source-shape pins: each warning site uses its constant (M16) ----

test('source-shape test: each unknown-key check in the parser uses its exported constant, not an inline list', () => {
  const pack = read('src/build/packtoml.js');
  const labels = read('src/build/labels.js');
  assert.ok(pack.includes('PACK_TOP_LEVEL_KEYS.includes('), 'packtoml.js must check top-level keys with PACK_TOP_LEVEL_KEYS');
  assert.ok(pack.includes('GM_LINK_KEYS.includes('), 'packtoml.js must check gm_link keys with GM_LINK_KEYS');
  assert.ok(!pack.includes("k !== 'theme'"), "packtoml.js still has an inline k !== 'theme' check");
  assert.ok(!pack.includes("k !== 'url'"), "packtoml.js still has an inline k !== 'url' check");
  assert.ok(labels.includes('KIND_ENTRY_KEYS.includes('), 'labels.js must check kind entry keys with KIND_ENTRY_KEYS');
  assert.ok(labels.includes('RECAPS_KEYS.includes('), 'labels.js must check recaps keys with RECAPS_KEYS');
  assert.ok(!labels.includes("k !== 'learned_heading'"), "labels.js still has an inline k !== 'learned_heading' check");
});

test('the four named lists have the literal contents the parser accepts', () => {
  const { PACK_TOP_LEVEL_KEYS, GM_LINK_KEYS } = require('../src/build/packtoml');
  const { KIND_ENTRY_KEYS, RECAPS_KEYS, TIMELINE_KEYS } = require('../src/build/labels');
  assert.deepEqual([...PACK_TOP_LEVEL_KEYS], ['theme', 'images', 'labels', 'timeline', 'recaps', 'gm_link']);
  assert.deepEqual([...GM_LINK_KEYS], ['url']);
  assert.deepEqual([...KIND_ENTRY_KEYS], ['key', 'label', 'glyph', 'aliases', 'before']);
  assert.deepEqual([...RECAPS_KEYS], ['learned_heading']);
  assert.deepEqual([...TIMELINE_KEYS], ['kinds', 'weights', 'session_token', 'segment_units', 'columns']);
  for (const list of [PACK_TOP_LEVEL_KEYS, GM_LINK_KEYS, KIND_ENTRY_KEYS, RECAPS_KEYS, TIMELINE_KEYS]) assert.ok(Object.isFrozen(list));
});
